    document.querySelectorAll('[data-uid]').forEach(b=>{b.onclick=()=>selectItem(+b.dataset.uid);b.addEventListener('pointerdown',e=>{b.setPointerCapture?.(e.pointerId);b.dataset.drag='true';});b.addEventListener('pointerup',e=>{const canvas=$('#board');if(!canvas)return;const r=canvas.getBoundingClientRect();if(e.clientX>=r.left&&e.clientX<r.right&&e.clientY>=r.top&&e.clientY<r.bottom){chosen=+b.dataset.uid;angle=0;place(...boardPoint(e));}});});
