  let flowPrepPress=null;
  function flowPrepPointerDown(e){const card=e.target.closest('[data-flow=seed]');if(!card||e.button!==0)return;flowPrepPress={id:+card.dataset.value,x:e.clientX,y:e.clientY,shown:false};flowPrepPress.timer=setTimeout(()=>{if(!flowPrepPress)return;flowPrepPress.shown=true;flowConfirm={type:'seed-info',id:flowPrepPress.id};syncFlowDialog(true);},500);}
